// Only public, already-observed allowance figures leave Claude Code.
const config = __CODEXIO_CONFIG__;
let sending = false;
let pending = null;
let last = null;
async function deliver($, usage) {
  try {
    const windows = (usage?.rateLimits ?? []).filter(w => ['five_hour','seven_day'].includes(w.kind))
      .filter(w => typeof w.percentUsed === 'number' && Number.isFinite(w.percentUsed) && w.percentUsed >= 0 && w.percentUsed <= 100)
      .map(w => ({kind:w.kind, percentUsed:w.percentUsed, resetsAt:typeof w.resetsAt === 'string'?w.resetsAt:null}));
    if (!(await $.fs.exists(config.runtime))) return;
    const runtime = JSON.parse(await $.fs.read(config.runtime));
    if (!runtime.url || !runtime.nonce || !runtime.url.startsWith("http://127.0.0.1:")) return;
    const now = await $.clock.now();
    const session = await $.session.id();
    const surfaces = await $.session.surfaces();
    const surface = surfaces.includes('desktop')?'desktop':'cli';
    const payload = {schema:1,source:'mods',surface,session_id:session,config_root:config.root,captured_at:now/1000,windows};
    const signature = JSON.stringify([session,windows,runtime.nonce]);
    if (last && last.signature === signature && now >= last.time && now-last.time < 60000) return;
    pending = {runtime,payload,signature,time:now};
    if (sending) return;
    sending = true;
    try {
      while (pending) {
        const value = pending; pending = null;
        const result = await $.http.fetch(value.runtime.url, {method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+value.runtime.nonce},body:JSON.stringify(value.payload)});
        if (result.ok) last = {signature:value.signature,time:value.time};
      }
    } finally {sending = false;}
  } catch { /* Allowance capture never changes the user's turn or interface. */ }
}
export const register = on => {
  on('session.start', async ($,e,next) => {try {await deliver($,await $.session.usage());} catch {} return next(e);});
  on('session.measure', async ($,e,next) => {if (!e.changed || e.changed.includes('rateLimits')) await deliver($,e);return next(e);});
  on('turn.complete', async ($,e,next) => {try {await deliver($,await $.session.usage());} catch {} return next(e);});
};
